package dev.jpm.resolve;

import dev.jpm.util.Fs;
import dev.jpm.util.JpmException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class LockfileConflictTest {
    private static final String CONFLICTED = """
            // Generated by jpm. Do not edit by hand.
            {
              "lockfileVersion": 1,
            <<<<<<< HEAD
              "inputs": "aaaa",
            =======
              "inputs": "bbbb",
            >>>>>>> feature
              "packages": {
                "a:common": { "version": "1.0.0" },
            <<<<<<< HEAD
                "a:lib": { "version": "1.2.0" },
                "a:ours": { "version": "1.0.0" }
            ||||||| base
                "a:lib": { "version": "1.0.0" }
            =======
                "a:lib": { "version": "1.1.0" },
                "a:theirs": { "version": "2.0.0" }
            >>>>>>> feature
                "z:last": { "version": "3.0.0" }
              }
            }
            """;

    @Test
    void bothSidesAreMergedAndTheHigherVersionWins(@TempDir Path tmp) {
        Path file = tmp.resolve("project.lock");
        Fs.write(file, CONFLICTED);
        Lockfile lock = Lockfile.read(file);
        assertTrue(lock.conflicted);
        assertNull(lock.inputs, "a conflicted lockfile is always resolved again");
        assertEquals("1.2.0", lock.graph.get("a:lib").version);
        assertEquals("1.0.0", lock.graph.get("a:ours").version);
        assertEquals("2.0.0", lock.graph.get("a:theirs").version);
        assertEquals("1.0.0", lock.graph.get("a:common").version);
        assertEquals("3.0.0", lock.graph.get("z:last").version);
    }

    @Test
    void aFileWithoutMarkersIsNotConflicted(@TempDir Path tmp) {
        Path file = tmp.resolve("project.lock");
        Fs.write(file, "{ \"lockfileVersion\": 1, \"inputs\": \"x\", \"packages\": {} }");
        assertFalse(Lockfile.read(file).conflicted);
        assertFalse(Lockfile.hasConflictMarkers(Fs.read(file)));
    }

    @Test
    void aConflictNeitherSideCanReadSaysWhatToDo(@TempDir Path tmp) {
        Path file = tmp.resolve("project.lock");
        Fs.write(file, "<<<<<<< HEAD\n{ broken\n=======\nalso broken\n>>>>>>> other\n");
        JpmException e = assertThrows(JpmException.class, () -> Lockfile.read(file));
        assertTrue(e.getMessage().contains("git checkout --theirs"), e.getMessage());
    }
}
